{
  "probability": 0.01,
  "range_low": 0.01,
  "range_high": 0.02,
  "summary": [
    "Posterior probability that AfD wins the most seats in Baden-Württemberg is 1%.",
    "Polling leads of CDU/Greens over AfD and historical base-rate strongly argue against AfD top seat.",
    "Seat projections consistently show CDU/Greens ahead; AfD not on track to top the tally."
  ],
  "confidence": "high",
  "narrative": "Starting from the Baden-Württemberg reference class, multiple strong downward updates from polls and historical precedent reduce AfD's chances to near-zero. The posterior is 1% with a narrow uncertainty band, reflecting high confidence in a CDU/Greens-led outcome rather than AfD-leading the seat counts.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "Reference class is Baden-Württemberg state elections in multiparty systems where AfD has not led; anchor probability reflects typical base-case probability of any one party achieving top-seat status in this environment"
    },
    "factor_updates": [
      {
        "factor": "Lead of CDU/Greens in polls",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Consistent polls place CDU/Greens ahead of AfD (roughly 27–28% vs 18–19%), making AfD top-seat unlikely."
      },
      {
        "factor": "Historical base-rate for BW leading party",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Historically, AfD has not led BW; Greens or CDU have the top vote shares in past elections."
      },
      {
        "factor": "Seat-projection consensus",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Forecasts from FGW, INSA, and INSA-like polls project CDU/Greens ahead with AfD not topping seat counts."
      },
      {
        "factor": "Coalition dynamics excluding AfD",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Coalitions typically involve CDU/Greens; AfD would need a top-seat count to break typical governance blocs, unlikely."
      },
      {
        "factor": "Low base-rate for AfD to win most seats",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Base-rate analyses estimate very low probability (roughly 0–5%), reinforcing a near-zero posterior for top-seat outcome."
      }
    ],
    "synthesis_rationale": "The factors were integrated by steeply down-weighting the anchor due to multiple independent, strong-down signals from polls, historical precedent, and seat projections. The calibration accounts for potential correlations by treating the factors as converging evidence rather than strictly independent, yielding a cautious, low-probability posterior around 1%."
  }
}

{
