  "narrative": "Current evidence assigns a 1% posterior probability to AfD winning the most seats in BW, reflecting strong polling leads for CDU/Greens and historical patterns. There remains limited upside from turnout or late swings, but the likelihood stays very small.",
  "justification": {
    "anchor": {
      "probability": 0.04,
      "basis": "Baseline, historically observed in BW where AfD has not led seat totals; anchor chosen to reflect a modest starting probability before downward updates from polls and projections."
    },
    "factor_updates": [
      {
        "factor": "Lead of CDU/Greens in polls",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Consistent polling shows CDU/Greens ahead of AfD, which lowers AfD's odds of leading."
      },
      {
        "factor": "Historical base-rate for AfD leading BW",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Past elections never had AfD as the largest party in BW."
      },
      {
        "factor": "Seat-projection consensus",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Forecasts project CDU/Greens majority; AfD not on track to top seat counts."
      },
      {
        "factor": "Coalition dynamics excluding AfD",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "BW's multi-party system tends to produce coalitions without AfD; top-seat status remains unlikely."
      },
      {
        "factor": "Low base-rate for AfD to win most seats",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Base-rate analyses place AfD in the low single digits; 1% posterior aligns with that."
      }
