    "synthesis_rationale": "The final estimate is derived by steep downward updates from strong polling leads and seat projections, anchored on a conservative base-rate; even allowing mild upward risks does not materially raise the posterior above a few percent."
  }
}

{
  "probability": 0.08,
  "range_low": 0.04,
  "range_high": 0.15,
  "summary": [
    "Polls place CDU/Greens ahead of AfD in Baden-Württemberg, with AfD typically around 18–21% and not the largest party.",
    "Historical baselines and multiple seat projections imply AfD is not on track to win the most seats.",
    "A contrarian tail-risk exists: turnout shifts or late-stage dynamics could modestly raise AfD odds, but the likelihood remains very small."
  ],
  "confidence": "low",
  "narrative": "Despite strong polling for CDU/Greens, there is a plausible tail-risk scenario where AfD could overperform enough to threaten the top seat total. However, the converging polls, historical precedent, and seat projections keep the probability at a low single-digit to low-double-digit level; this forecast weights the downside heavily but notes a small upside from turnout or late swing.",
  "justification": {
    "anchor": {
      "probability": 0.05,
      "basis": "reference class anchored to Baden-Württemberg state elections where AfD has never led and where Greens or CDU have historically won the most seats; anchor probability reflects the prevailing base-rate and pre-election polls."
    },
    "factor_updates": [
      {
        "factor": "Lead of CDU/Greens in polls (Feb 2026)",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Polls consistently show CDU and Greens ahead of AfD (CDU ~27–28%, Greens ~22–27%, AfD ~18–21%), making AfD unlikely to be the largest party."
      },
      {
        "factor": "Historical base-rate for AfD leading BW",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Historically, AfD has not led BW; Greens or CDU have topped vote shares in past elections."
      },
      {
        "factor": "Seat-projection consensus",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Forecasts project CDU/Greens ahead with AfD not on track to win the most seats."
      },
      {
        "factor": "Coalition dynamics excluding AfD",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "BW coalitions typically CDU/Greens; AfD not in top coalition options, reducing odds of top-seat outcome."
      },
      {
        "factor": "Turnout surge among AfD core voters",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A turnout surge among AfD's core could lift their vote share into the low 20s, providing a tail-risk."
      },
      {
        "factor": "Local issues or campaign dynamics",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Contemporary concerns could erode governing-party leads more than AfD, closing the gap marginally."
      },
      {
        "factor": "Polling biases or late swings",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Uncertainty around survey methods or last-minute shifts could modestly inflate AfD odds, though not decisively."
      }
    ],
    "synthesis_rationale": "The final estimate weights the strong, cross-cutting evidence that AfD is not on track to lead BW, with a cautious allowance for tail risks via turnout dynamics and last-minute shifts. Calibration favors conservative probability, but the contrarian inputs provide a nonzero upside. The range reflects uncertainty and the possibility of outliers or late dynamics; the anchor remains the historical baseline and current polls."
  }
}
